const char* getNamedResource (const char* resourceNameUTF8, int& numBytes)
{
    unsigned int hash = 0;

    if (resourceNameUTF8 != nullptr)
        while (*resourceNameUTF8 != 0)
            hash = 31 * hash + (unsigned int) *resourceNameUTF8++;

    switch (hash)
    {
        case 0x663b186c:  numBytes = 416; return stop_png;
        case 0xf232c4a6:  numBytes = 878; return loading_png;
        case 0x7000b29e:  numBytes = 774; return play_png;
        case 0x8693b60e:  numBytes = 1084; return loop_png;
        case 0x54ebbadd:  numBytes = 1078; return next_png;
        case 0xbd6c48e1:  numBytes = 1044; return previous_png;
        default: break;
    }

    numBytes = 0;
    return nullptr;
}

